//! What a field element is: a Montgomery-domain limb array, and the residue
//! it stands for. The vocabulary of fiat-crypto's printed conditions.
//!
//! # Source (pinned)
//!
//! **fiat-crypto 0.3.0** (crates.io, `Cargo.lock` checksum
//! `64cd1e32ddd350061ae6edb1b082d7c54915b5c672c389143b9a63403a109f24`),
//! generated by `word_by_word_montgomery`:
//!
//! - `src/p384_64.rs`, SHA-256
//!   `2dab86b68de2533016b4226f029f82951393819bad0956cff97e33e754a74765`: the
//!   field GF(p), `m = 0xfff...fffeffffffff0000000000000000ffffffff`
//!   (printed in its header, equal to `2^384 - 2^128 - 2^96 + 2^32 - 1`);
//! - `src/p384_scalar_64.rs`, SHA-256
//!   `df99d668d71d98640aad16bea65354f6a511ee0a24891f439ae4be0165164a06`: the
//!   integers mod n, `m = 0xfff...fffc7634d81f4372ddf581a0db248b0a77aecec196accc52973`
//!   (printed in its header, equal to n).
//!
//! The two files have the same shape. Each function documents, above its
//! signature, a `Preconditions` and a `Postconditions` block; those blocks
//! are what `axioms.rs` copies. This file gives their words a meaning.
//!
//! # Modelling choices
//!
//! 1. **`eval` is [`value`].** Fiat's header defines `eval z = z[0] + (z[1]
//!    << 64) + ... + (z[5] << 0x140)`. [`value`] is the same sum for a
//!    sequence of any length (as `clazel-pkcs1`'s bignum `value`), and a
//!    field element is a sequence of exactly 6 limbs, each below 2^64 by its
//!    type. That is fiat's "unique saturated representation" ("the input is
//!    in the unique saturated representation"); the only other requirement
//!    its blocks print is `eval z < m`.
//! 2. **`m` is [`modulus`]**: the `p` or the `n` of [`crate::spec::p384`],
//!    not a second copy of the constant. That it is the number fiat's header
//!    prints as `m` was compared digit by digit with a script when this file
//!    was written; fiat's `m` is a comment, so no proof can check it, and
//!    `tests/field.rs` checks it indirectly (arithmetic modulo it agrees with
//!    Python's).
//! 3. **`from_montgomery` is [`from_montgomery`].** Fiat's `mul`, `add` and
//!    `sub` are stated through `eval (from_montgomery z)`, where
//!    `from_montgomery` is fiat's own function, whose printed postcondition
//!    is `eval out mod m = (eval z * ((2^64)⁻¹ mod m)^6) mod m` and `0 <= eval
//!    out < m`. So `eval (from_montgomery z)` is that residue, in `[0, m)`.
//!    The spec writes it as fiat does, with `(2^64)⁻¹ mod m` a number
//!    ([`base_inv`], one literal per modulus). Writing the inverse as a
//!    literal needs no primality; that it is an inverse is a ground fact
//!    (`lemmas.rs`, `lemma_rinv`).
//! 4. **The residue a limb array stands for** is its `from_montgomery`. With
//!    `R = 2^384`, [`mont`]`(x) = x R mod m` is the Montgomery form of `x`,
//!    and `from_montgomery(mont(x)) = x` (`lemmas.rs`, `lemma_mont_roundtrip`).
//!    The code never needs `mont` itself: it converts by fiat's `mul` (by
//!    `R^2 mod m` and by 1).
//! 5. **Subtraction** is `(x - y) mod m` for the residues `x` and `y`, the
//!    mathematical modulus, which is [`crate::spec::fe_sub`].

#[allow(unused_imports)]
use vstd::prelude::*;

verus! {

/// Which of fiat's two generated modules: `p384_64` (the field GF(p), for
/// coordinates) or `p384_scalar_64` (the integers mod n, for scalars).
#[derive(Clone, Copy, PartialEq, Eq)]
pub enum Which {
    /// Arithmetic mod p, fiat's `p384_64`.
    P,
    /// Arithmetic mod n, fiat's `p384_scalar_64`.
    N,
}

/// Fiat's `m`: p for [`Which::P`], n for [`Which::N`] (choice 2).
pub open spec fn modulus(w: Which) -> nat {
    match w {
        Which::P => crate::spec::p384().p,
        Which::N => crate::spec::p384().n,
    }
}

/// The radix of a limb, 2^64.
pub open spec fn base() -> nat {
    0x1_0000_0000_0000_0000nat
}

/// `base()^i`, the weight of limb `i`.
pub open spec fn limb_pow(i: nat) -> nat
    decreases i,
{
    if i == 0 {
        1
    } else {
        limb_pow((i - 1) as nat) * base()
    }
}

/// Fiat's `eval` (choice 1): `z[0] + z[1] 2^64 + z[2] 2^128 + ...`.
pub open spec fn value(z: Seq<u64>) -> nat
    decreases z.len(),
{
    if z.len() == 0 {
        0
    } else {
        value(z.drop_last()) + (z.last() as nat) * limb_pow((z.len() - 1) as nat)
    }
}

/// `R = 2^384`, the Montgomery radix of six 64-bit limbs.
pub open spec fn radix() -> nat {
    limb_pow(6)
}

/// `(2^64)⁻¹ mod m` as a number in `[0, m)` (choice 3).
pub open spec fn base_inv(w: Which) -> nat {
    match w {
        Which::P => 0x00000001_00000000_ffffffff_ffffffff_ffffffff_ffffffff_ffffffff_ffffffff_fffffffe_fffffffd_ffffffff_00000001nat,
        Which::N => 0x6ed46089_e88fdc44_ffffffff_ffffffff_ffffffff_ffffffff_e77db430_c4555788_7cd47351_23d969cd_0432fa0c_a03b08afnat,
    }
}

/// Fiat's `eval (from_montgomery z)` (choice 3): `(eval z * ((2^64)⁻¹ mod
/// m)^6) mod m`, which is in `[0, m)`.
pub open spec fn from_montgomery(w: Which, z: Seq<u64>) -> nat {
    value(z) * (base_inv(w) * base_inv(w) * base_inv(w) * base_inv(w) * base_inv(w) * base_inv(w))
        % modulus(w)
}

/// The Montgomery form of the residue `x` (choice 4): `x R mod m`.
pub open spec fn mont(w: Which, x: nat) -> nat {
    x * radix() % modulus(w)
}

} // verus!
